import{j as e}from"./vendor-react-BlVc7RbY.js";import{P as a}from"./ProblemPage-KaPViw5X.js";import"./vendor-misc-BAGPFqjl.js";import"./index-BlrmFtr-.js";import"./vendor-ui-D7glRu94.js";import"./vendor-framer-motion-_M9ViFvP.js";import"./Breadcrumb-H_CkWXx7.js";function c(){return e.jsx(a,{slug:"aquecimento-exterior",pageTitle:"Aquecimento Exterior: Aquecedores para Esplanadas, Terraços e Varandas",metaTitle:"Aquecimento Exterior para Esplanadas e Terraços | Evoluimos Comércio",metaDescription:"Aquecedores infravermelhos para esplanadas, terraços e varandas. Solamagic e ComfortSun, calor imediato, 92% de eficiência. Aumente a faturação do seu negócio o ano todo.",heroImage:"/Solamagic/aquecedorexterior.png",heroImageAlt:"Aquecedor infravermelho exterior numa esplanada",introParagraph:"No inverno, a esplanada pode ser a divisão mais rentável do restaurante, do bar ou do hotel. Com o aquecimento certo, mantém os clientes confortáveis com qualquer tempo e prolonga a estação alta o ano todo.",searchKeywords:["aquecimento exterior","aquecedor esplanada","aquecimento para esplanadas","aquecedor terraço","aquecedor infravermelho exterior"],problem:"Em Portugal, esplanadas e terraços fecham frequentemente entre Novembro e Março ou ficam vazios mesmo abertos, porque os clientes não estão dispostos a sentar-se ao frio. Para muitos restaurantes, bares e hotéis isto representa perda de 30 a 50% da receita possível em meses críticos. Sistemas tradicionais de aquecimento exterior (cogumelos a gás) são ineficientes, ruidosos, dependem de bilhas e não fornecem calor verdadeiramente confortável.",causes:[{title:"Calor que se dispersa no ar exterior",text:"Sistemas que aquecem o ar não funcionam ao ar livre. O calor sobe e dissipa-se em segundos. Cogumelos a gás aquecem essencialmente o ar logo acima, não as pessoas em redor."},{title:"Vento e temperatura ambiente",text:"Mesmo dias amenos podem ficar desagradáveis com vento moderado. Quando a temperatura desce abaixo dos 15 graus à noite, é raro encontrar clientes em mesas exteriores sem aquecimento adequado."},{title:"Custo de operação alto",text:"Cogumelos a gás propano consomem entre 0,5 e 1 kg de gás por hora. Para várias horas e várias unidades, o custo mensal acumula rapidamente. Além disso, exige logística de troca de bilhas."},{title:"Imagem e ruído",text:"Cogumelos a gás ocupam espaço, são visualmente intrusivos, libertam CO2 directo sobre os clientes e produzem ruído de combustão. Não combinam com a imagem de estabelecimentos premium."}],consequences:["Perda de 30 a 50% da faturação possível entre Novembro e Março","Esplanadas vazias mesmo em dias com clima razoável","Custos elevados com gás e logística de bilhas","Impacto ambiental significativo, com emissão directa de CO2 sobre clientes","Pressão sobre o espaço interior e perda de margem","Imagem do estabelecimento prejudicada por equipamentos intrusivos"],solution:"O aquecimento por infravermelhos de onda curta resolve o problema. Em vez de aquecer o ar, aquece directamente pessoas, mesas e cadeiras, como o Sol. O resultado é calor imediato, mesmo em zonas abertas com vento ligeiro. A Solamagic é o sistema de referência mundial, fabricada na Alemanha, com 92% de eficiência radiante. A ComfortSun oferece quatro linhas (Polivalente, Professional, Especializado, Deluxe) para diferentes orçamentos e estéticas. Em conjunto, cobrem qualquer tipologia de esplanada, terraço ou varanda.",benefits:["Calor imediato em segundos, sem tempo de aquecimento","92% de eficiência radiante, vs 25 a 40% dos sistemas a gás","Sem combustão, sem CO2, sem bilhas e sem ruído","Compatível com painéis fotovoltaicos, custo operacional pode aproximar-se de zero","Discreto e elegante, várias opções estéticas e de cor","Aumento típico de faturação de 30 a 50% em esplanadas"],process:[{title:"Visita técnica gratuita",text:"Medimos a esplanada ou terraço, analisamos exposição ao vento, altura de instalação e orientação. Planeamos cobertura térmica óptima."},{title:"Escolha do sistema",text:"Solamagic para o segmento premium ou polivalente, ComfortSun Professional para hotelaria, Polivalente para varandas residenciais. Definimos potências e ângulos."},{title:"Instalação profissional",text:"Instalação eléctrica certificada, fixação adequada e teste de funcionamento. Tipicamente em 1 a 2 dias para uma esplanada média."},{title:"Otimização sazonal",text:"Configuramos o sistema de controlo (interruptores, dimmers, automação) para utilização eficiente conforme a meteorologia."}],faqs:[{question:"Como funciona o aquecimento exterior por infravermelhos?",answer:"Os aquecedores Solamagic e ComfortSun emitem radiação infravermelha de onda curta, que aquece directamente pessoas e objectos, sem aquecer o ar. É a mesma sensação do Sol num dia de inverno: o ar pode estar a 10 graus, mas a pele sente conforto."},{question:"Funcionam mesmo com vento?",answer:"Sim. Como a radiação infravermelha aquece directamente as superfícies, é praticamente imune ao vento ligeiro a moderado. É a grande vantagem face aos sistemas a gás, que dependem de aquecer o ar (e o ar dispersa-se com vento)."},{question:"Quanto consomem em eletricidade?",answer:"Um aquecedor Solamagic de 2 kW consome 2 kWh por hora. A custo médio de eletricidade comercial em Portugal, são cerca de 0,30 a 0,50 euros por hora. Com painéis fotovoltaicos, o custo operacional aproxima-se de zero durante o dia."},{question:"Quantos aquecedores preciso para uma esplanada?",answer:"Depende da área, da altura de instalação e da exposição ao vento. Como regra de polegar, um aquecedor de 2 kW cobre confortavelmente uma área de 4 a 8 metros quadrados a 2,5 metros de altura. Fazemos cálculo personalizado na visita técnica."},{question:"É possível instalar em varandas residenciais?",answer:"Sim. Temos modelos compactos para varandas e terraços residenciais, com instalação discreta na parede ou no tecto. ComfortSun Deluxe e Polivalente são as opções típicas."},{question:"A instalação é fixa ou móvel?",answer:"Maioritariamente fixa, em parede ou tecto, mas também existem modelos com tripé ou pendurados, para utilizações temporárias ou eventos. Recomendamos a fixa para hotelaria."},{question:"Aquecedores Solamagic emitem luz?",answer:"Sim, uma luz quente discreta com tonalidade âmbar (modelos Eco) ou branca (modelos Pure). Pode ser ajustada com filtros opcionais. Muitos clientes valorizam a luz como elemento ambiental adicional."},{question:"Que garantia oferecem?",answer:"Solamagic tem garantia de 2 anos no equipamento, com lâmpadas de longa duração (até 8000 horas). ComfortSun varia entre 2 e 5 anos conforme modelo. Apoio técnico em todo o Portugal."}],relatedProducts:[{label:"Solamagic Premium",path:"/products/solamagic"},{label:"ComfortSun (todas as linhas)",path:"/products/comfortsun"},{label:"ComfortSun Professional",path:"/products/comfortsun/professional"},{label:"ComfortSun Deluxe",path:"/products/comfortsun/deluxe"}],relatedSolutions:[{label:"Aquecer esplanadas e terraços",path:"/solutions/outdoor-comfort"},{label:"Soluções para empresas",path:"/solutions/sustainable-business"},{label:"Aquecimento sem obras",path:"/aquecimento-sem-obras"}],serviceName:"Aquecimento exterior para esplanadas e terraços",serviceType:"Aquecimento por infravermelhos para exteriores"})}export{c as default};
